+    control_path = None
+    last_path = None
+
+
+class CannedHandler(http.server.BaseHTTPRequestHandler):
+    def _read_body(self):
+        length = int(self.headers.get("Content-Length", 0))
+        return self.rfile.read(length).decode("utf-8", errors="replace")
