String _dismissPrReview(GhSyncConfig c, Map<String, dynamic> a) =>
    syncBodyOrError(SyncHttpClient.put(
      '${_prUrl(c, a)}/reviews/${syncAsStr(a['reviewId'])}/dismissals',
      headers: c.headers,
      body: jsonEncode({
        'message': syncAsStr(a['message']),
        'event': 'DISMISS',
      }),
    ));

