  _LoadedScript _loadJavaScriptCode(String jsSourceOrPath) {
    if (jsSourceOrPath.startsWith('http://') ||
        jsSourceOrPath.startsWith('https://')) {
      return _LoadedScript(
        _loadFromUrl(jsSourceOrPath),
