/// Replays a Jira fixture against a mocked [JiraClient].
///
/// Returns the Dart tool's output for comparison with the fixture's
/// `expected_response`.
Future<Object?> _replayJira(ContractFixture f) async {
  final fix = mockJira((_) => f.mockBody);
  switch (f.toolName) {
