      if (multipartFile != null) ...['-F', 'file=@$multipartFile'],
      if (outputFile != null) ...['-o', outputFile],
      url,
    ];
    return SyncHttpClient.parseResponse(
      Process.runSync('curl', args, stdoutEncoding: utf8),
    );
  } finally {
